    value = _cache.get(key)
    if value is not None:
        return value
    value = key.encode() * 1_000_000
    _cache[key] = value
    return value
```

---

## Minimal Go Example (Leak)

```go
// leak.go
package main

// Package-level map cache: entries are never deleted.
var cache = map[string][]byte{}

func getOrCompute(key string) []byte {
	// BUG: cache grows without bound; each entry pins a large slice.
	if v, ok := cache[key]; ok {
		return v
	}
	v := make([]byte, 1<<20) // ~1 MB per key
	for i := range v {
		v[i] = key[0]
	}
	cache[key] = v
	return v
}

func main() {
	for i := 0; i < 100000; i++ {
		getOrCompute("item-" + string(rune('A'+i%26)) + string(rune(i)))
	}
}
```

The map holds strong references to every slice; Go's GC won't free them because they remain reachable.

---

## Fix (Go)

### Bounded cache with eviction

```go
package main

import "container/list"

const maxEntries = 1024

type entry struct {
	key   string
	value []byte
}

// Cache is a simple LRU cache with a hard size cap.
type Cache struct {
	items map[string]*list.Element
	ll    *list.List
}

func NewCache() *Cache {
	return &Cache{items: make(map[string]*list.Element), ll: list.New()}
}

func (c *Cache) Get(key string) ([]byte, bool) {
	if el, ok := c.items[key]; ok {
		c.ll.MoveToFront(el) // mark recently used
		return el.Value.(*entry).value, true
	}
	return nil, false
}

func (c *Cache) Add(key string, value []byte) {
	if el, ok := c.items[key]; ok {
		c.ll.MoveToFront(el)
		el.Value.(*entry).value = value
		return
	}
	el := c.ll.PushFront(&entry{key, value})
	c.items[key] = el
	if c.ll.Len() > maxEntries {
		// Evict least-recently-used entry; its slice becomes unreachable
		// and will be collected by the GC.
		oldest := c.ll.Back()
		if oldest != nil {
			c.ll.Remove(oldest)
			delete(c.items, oldest.Value.(*entry).key)
		}
	}
}

func getOrCompute(key string) []byte {
	if v, ok := globalCache.Get(key); ok {
		return v
	}
	v := make([]byte, 1<<20)
	for i := range v {
		v[i] = key[0]
	}
	globalCache.Add(key, v)
	return v
}

var globalCache = NewCache()

func main() {
	for i := 0; i < 100000; i++ {
		getOrCompute("item-" + string(rune('A'+i%26)) + string(rune(i)))
	}
}
```

---

## Key Takeaways

1. In GC languages, a leak = **reachable but useless** memory, not a missing `free()`.
2. The GC cannot read your mind; if you hold a reference (global, container, closure, goroutine), the object survives.
3. The fix is almost always about **lifecycle management**: bound your caches, unregister listeners, cancel goroutines, and use weak references when a cache shouldn't extend an object's lifetime.
4. Detect leaks with tools like `tracemalloc`/`objgraph` (Python) or `pprof` heap profiles (Go) — look for memory that grows monotonically across operations that should be steady-state.

